  "version": 1,
  "questions": {
    "kind": {
      "choose": "What kind of message is this?",
      "options": ["billing", "bug", "question"]},
    "urgency": {
      "score": "How urgent is this?",
      "levels": ["Routine.", "Soon.", "Immediate."]}
  }
}

reduce inputs as $l ({file: null, hunks: []};
  if ($l | startswith("+++ b/")) then .file = $l[6:]
  elif ($l | startswith("@@")) then .hunks += [{file, at: $l, hunk: ""}]
  elif (.hunks | length) > 0 and ($l | test("^(diff |--- )") | not)
  then .hunks[-1].hunk += $l + "\n"
  else . end)
| .hunks[]

